import React from "react";
import { Avatar, IconButton, Button } from "../../index";
import { SvgMpaIcon } from "../../assets/icons/index";
import "./VerticalButtonCard.scss";

export interface VerticalButtonCardProps {
  id?: string;
  cardType?: "elevated" | "filled" | "outline";
  types?: "Card01" | "Card02";
  headerTitle?: string;
  subHeadTitle?: string;
  avatarText?: string;  
  imageUrl?: string;
  headerButtonIcon?: keyof typeof SvgMpaIcon | string;
  showImage?: boolean;
  showHeader?: boolean;
  showHeaderIconButton?: boolean;
  showDivider?: boolean;
  showCTA?: boolean;
  showSuplementalIconButton?: boolean;  
  title?: string;
  subText?: string;
  description?: string;
  primaryIcon?: keyof typeof SvgMpaIcon | string;
  secondaryIcon?: keyof typeof SvgMpaIcon | string;  
  onPrimaryActionClick?: () => void;
  onSecondaryActionClick?: () => void;
  onPrimarIconButtonClick?: () => void;
  onSecondaryIconButtonClick?: () => void;
  onHeaderIconButtonClick?: () => void;
  disabled?: boolean
}

const VerticalButtonCard: React.FC<VerticalButtonCardProps> = ({
  id,
  cardType = "elevated",
  types = "Card01",
  headerTitle,
  subHeadTitle,
  avatarText,
  showImage = true,
  imageUrl,
  headerButtonIcon,
  showHeader = true,  
  showHeaderIconButton = true,
  showDivider = true,
  showCTA = true,
  showSuplementalIconButton = true,
  title,
  subText,
  description,
  primaryIcon,
  secondaryIcon,
  onPrimaryActionClick,
  onSecondaryActionClick,
  onPrimarIconButtonClick,
  onSecondaryIconButtonClick,  
  onHeaderIconButtonClick,
  disabled = false
}) => {
  const showimageFullWidth = types === "Card01";

  return (
    <div className={`mpa-cardLayoutWrapper ${disabled ? "disabled" : ""} ${cardType}`}>
      {showHeader && (
        <div className="mpa-cardHeader">
          <div className="mpa-CardHeaderContainer">
            <Avatar
                id="avatar"
                colour="neutral"
                type="monogram"
                size="medium"
                username={avatarText}
              />
            <div className="mpa-titleContainer">
              <div className="mpa-title">{headerTitle}</div>
              <div className="mpa-subTitle">{subHeadTitle}</div>
            </div>
            {showHeaderIconButton && (
              <IconButton
                id={"id"}
                icon={headerButtonIcon}
                btnType="standard"
                size="medium"
                onClick={onHeaderIconButtonClick}
              />
            )}
          </div>
        </div>
      )}

      {showImage && (
        <div className={`mpa-CardImageContainer ${showimageFullWidth ? "full-width" : "with-padding"}`}>
          <img
            src={imageUrl}
            alt={(id ?? "") + " Description of image"}
            className="mpa-CardImage"
          />
        </div>
      )}

      <div className="mpa-CardSupportContainer">
        <div className="mpa-CardSupportTextContent">
          <div className="mpa-CardSupportTitle">{title}</div>
          <div className="mpa-CardSupportsubTitle">{subText}</div>
          <div className="mpa-CardSupportsubTitle">{description}</div>
        </div>

        {showCTA && (
           <div className="mpa-CardSupportActionContainer">
            {showDivider && <div className="mpa-CardSupportActionDivider"></div>}
            <div className="mpa-CardSupportActionButtonContainer">
              <div className="mpa-CardSupportNormalButtonContainer">
                <Button id="id" btnType="filled" onClick={onPrimaryActionClick} label="Action"></Button>
                <Button id="id" btnType="outline" onClick={onSecondaryActionClick} label="Action"></Button>
              </div>
              {showSuplementalIconButton && 
              <div className="mpa-CardSuplementalAction">
                <IconButton id="id" icon={primaryIcon} btnType="outline" shape="circle" size="medium" onClick={onPrimarIconButtonClick} />
                <IconButton id="id" icon={secondaryIcon} btnType="outline" shape="circle" size="medium" onClick={onSecondaryIconButtonClick} />
              </div>
              }              
            </div>
          </div>
        )}      
      </div>
    </div>
  );
};

export default VerticalButtonCard;
